INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 18, 'theory', 'Quiz: memory hierarchy and cache');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 18, 0, 'Why is a cache effective in most programs?', '["It stores all of memory", "Programs access memory non-randomly: recent data and neighboring addresses (locality)", "A cache is faster than the processor", "A cache is managed by the user"]', 1, 'Temporal and spatial locality let a small fast cache hold the data that will be needed soon.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 18, 1, 'Which fields are extracted from an address in a cache?', '["Tag, index, offset", "Header, body, signature", "Page, frame, flags", "Bank, row, module"]', 0, 'The offset is the byte within a line, the index picks the place or set, and the tag confirms the line holds the right block.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 18, 2, 'What is a conflict miss?', '["The cache is empty", "Blocks with the same index evict each other even though the cache has free space", "The data isn''t in memory", "A read error"]', 1, 'In a direct-mapped cache, two blocks with one index fight over a single line; associativity eases the problem.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 18, 3, 'What does write-back save compared with write-through?', '["Cache space", "Memory writes: with repeated writes to one line, a single write goes to memory on eviction", "Read time", "Power at shutdown"]', 1, 'The line is marked dirty, and only on eviction is its content written to memory.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 18, 4, 'An L1 cache answers in 1 cycle with 5% misses, and the average access to L2 is 50 cycles. What is the average access time?', '["1 cycle", "3.5 cycles", "50 cycles", "51 cycles"]', 1, 'AMAT = 1 + 0.05 × 50 = 3.5 cycles.');
